	@TempDir
	static File dataDir;

	private static SailRepository repository;
	private static String previousThreshold;
	private static String previousSynchronous;

	@BeforeAll
	static void setUp() {
		previousThreshold = System.getProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		previousSynchronous = System.getProperty(SYNCHRONOUS_CODEGEN_PROPERTY);
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		System.setProperty(SYNCHRONOUS_CODEGEN_PROPERTY, "true");
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			RDFInserter inserter = new RDFInserter(connection);
			ThemeDataSetGenerator.generateMedicalRecords(
					ThemeDataSetGenerator.medicalConfig().withPatientCount(400).withPractitionerCount(400), inserter);
			ThemeDataSetGenerator.generateSocialMedia(
					ThemeDataSetGenerator.socialMediaConfig().withUserCount(400).withPostsPerUser(4), inserter);
			connection.commit();
		}
	}

	@AfterAll
	static void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		if (previousThreshold == null) {
			System.clearProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		} else {
			System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", previousThreshold);
		}
		if (previousSynchronous == null) {
			System.clearProperty(SYNCHRONOUS_CODEGEN_PROPERTY);
		} else {
			System.setProperty(SYNCHRONOUS_CODEGEN_PROPERTY, previousSynchronous);
		}
	}

	@Test
	void queriesStayWithinTwentyLines() {
		List<String> tooLong = new ArrayList<>();
		CORPUS.forEach((name, body) -> {
			int lines = (PREFIXES + body).split("\n", -1).length;
			if (lines > 20) {
				tooLong.add(name + " (" + lines + " lines)");
			}
		});
		assertThat(tooLong).as("corpus entries longer than twenty lines").isEmpty();
	}

	/**
	 * Correctness gate over the same corpus: every query must return exactly the rows the generic RDF4J evaluator
	 * returns, as a multiset.
	 * <p>
	 * A decline census on its own can be satisfied by lowering something wrongly — the kernel engages, the reason
	 * disappears, and the answers change. This test is what makes the census safe to chase: it runs each query once
	 * with the native engine (kernel tier included, threshold zero) and once with {@code nativeQueryEngine.enabled} set
	 * to false, and compares the canonical row bags.
	 */
	@Test
	void adversarialResultsMatchGenericEvaluator() {
		List<String> mismatches = new ArrayList<>();
		CORPUS.forEach((name, body) -> {
			if (NON_DETERMINISTIC.contains(name)) {
				return;
			}
			String query = PREFIXES + body;
			List<String> nativeRows;
			List<String> genericRows;
			try {
				nativeRows = rows(query);
			} catch (RuntimeException problem) {
				mismatches.add(name + ": native evaluation failed: " + problem);
				return;
			}
			String previous = System.getProperty(NATIVE_FLAG);
			try {
				System.setProperty(NATIVE_FLAG, "false");
				genericRows = rows(query);
			} catch (RuntimeException problem) {
				mismatches.add(name + ": generic evaluation failed: " + problem);
				return;
			} finally {
				if (previous == null) {
					System.clearProperty(NATIVE_FLAG);
				} else {
					System.setProperty(NATIVE_FLAG, previous);
				}
			}
			if (!nativeRows.equals(genericRows)) {
				mismatches.add(name + ": native " + nativeRows.size() + " rows vs generic " + genericRows.size()
						+ " rows; first difference " + firstDifference(nativeRows, genericRows));
			}
		});
		assertThat(mismatches).as("adversarial queries whose native results differ from the generic evaluator")
				.isEmpty();
	}

	private static String firstDifference(List<String> left, List<String> right) {
		for (int i = 0; i < Math.min(left.size(), right.size()); i++) {
			if (!left.get(i).equals(right.get(i))) {
				return "at " + i + ": native=" + left.get(i) + " generic=" + right.get(i);
			}
		}
		List<String> longer = left.size() > right.size() ? left : right;
		return "extra row in " + (left.size() > right.size() ? "native" : "generic") + ": "
				+ longer.get(Math.min(left.size(), right.size()));
	}

	/** Canonical, order-independent rendering of a query's solutions, so comparison is a multiset comparison. */
	private static List<String> rows(String query) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			org.eclipse.rdf4j.query.TupleQuery prepared = connection.prepareTupleQuery(query);
			prepared.setMaxExecutionTime(QUERY_TIMEOUT_SECONDS);
			List<org.eclipse.rdf4j.query.BindingSet> result = org.eclipse.rdf4j.query.QueryResults
					.asList(prepared.evaluate());
			return result.stream().map(bindings -> {
				List<String> names = new ArrayList<>(bindings.getBindingNames());
				java.util.Collections.sort(names);
				StringBuilder row = new StringBuilder();
				for (String binding : names) {
					row.append(binding).append('=').append(bindings.getValue(binding)).append(';');
				}
				return row.toString();
			}).sorted().collect(java.util.stream.Collectors.toList());
		}
	}

	@Test
	void adversarialSpecializedDeclinesStayOnTheSemanticNativeFloor() throws IOException {
		Map<String, Set<String>> byReason = new LinkedHashMap<>();
		Map<String, Set<String>> byQuery = new LinkedHashMap<>();
		Map<String, String> failures = new LinkedHashMap<>();

		CORPUS.forEach((name, body) -> {
			String query = PREFIXES + body;
			Set<String> reasons;
			long started = System.nanoTime();
			try {
				reasons = declineReasons(query);
			} catch (RuntimeException problem) {
				failures.put(name, String.valueOf(problem));
				System.out.println(String.format("%-30s FAILED  %s", name, problem));
				return;
			}
			System.out.println(String.format("%-30s %5d ms  %s", name, (System.nanoTime() - started) / 1_000_000L,
					reasons.isEmpty() ? "engaged" : String.join(", ", reasons)));
			for (String reason : reasons) {
				String bare = reason.substring(reason.indexOf(':') + 1);
				if (isAllowedSemanticHandoff(bare)) {
					continue;
				}
				byReason.computeIfAbsent(reason, key -> new LinkedHashSet<>()).add(name);
				byQuery.computeIfAbsent(name, key -> new LinkedHashSet<>()).add(reason);
			}
		});

		String report = render(byReason, byQuery, failures);
		System.out.println(report);
		Files.writeString(reportFile(), report);

		assertThat(failures).as("adversarial queries that failed to execute").isEmpty();
		assertThat(byQuery).as("adversarial queries still declining (report at %s):%n%s", reportFile(), report)
				.isEmpty();
	}

	private static boolean isAllowedSemanticHandoff(String bareReason) {
		return NON_CAPABILITY_REASONS.contains(bareReason) || SEMANTIC_NATIVE_REASONS.contains(bareReason);
	}

	@Test
	void nativeSubqueryDeclineIsASemanticNativeFloorHandoff() {
		assertThat(isAllowedSemanticHandoff("child:NativeSubqueryPlan"))
				.as("the specialized IR tier may hand a subquery to its semantic NativeSubqueryPlan cursor")
				.isTrue();
	}

	private static Set<String> declineReasons(String query) {
		Set<String> reasons = new LinkedHashSet<>();
		for (int run = 0; run < WARMUP_RUNS; run++) {
			reasons.clear();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				org.eclipse.rdf4j.query.TupleQuery prepared = connection.prepareTupleQuery(query);
				prepared.setMaxExecutionTime(QUERY_TIMEOUT_SECONDS);
				collectDeclineReasons(prepared.explain(Explanation.Level.Telemetry).toGenericPlanNode(), reasons);
			}
			boolean onlyWarmup = !reasons.isEmpty() && reasons.stream()
					.allMatch(reason -> isAllowedSemanticHandoff(reason.substring(reason.indexOf(':') + 1)));
			if (!onlyWarmup) {
				return reasons;
			}
		}
		return reasons;
	}

	private static void collectDeclineReasons(GenericPlanNode node, Set<String> reasons) {
		if (node == null) {
			return;
		}
		String declines = node.getStringMetricActual("nativeStrategyDeclines");
		if (declines != null) {
			Matcher matcher = KERNEL_DECLINE.matcher(declines);
			while (matcher.find()) {
				reasons.add(matcher.group(1) + ":" + matcher.group(2));
			}
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectDeclineReasons(child, reasons);
			}
		}
	}

	private static String render(Map<String, Set<String>> byReason, Map<String, Set<String>> byQuery,
			Map<String, String> failures) {
		StringBuilder out = new StringBuilder();
		out.append("=== Adversarial kernel decline report ===\n");
		out.append("queries=").append(CORPUS.size()).append(" declining=").append(byQuery.size()).append('\n');
		out.append("\n-- by reason --\n");
		byReason.entrySet()
				.stream()
				.sorted((a, b) -> Integer.compare(b.getValue().size(), a.getValue().size()))
				.forEach(entry -> out.append(String.format("%4d  %-46s %s%n", entry.getValue().size(), entry.getKey(),
						String.join(", ", entry.getValue()))));
		if (byReason.isEmpty()) {
			out.append("      (none)\n");
		}
		out.append("\n-- by query --\n");
		byQuery.forEach((name, reasons) -> out
				.append(String.format("      %-30s %s%n", name, String.join(", ", reasons))));
		if (!failures.isEmpty()) {
			out.append("\n-- failed to execute --\n");
			failures.forEach((name, problem) -> out.append("      ")
					.append(name)
					.append(": ")
					.append(problem)
					.append('\n'));
		}
		return out.toString();
	}

	private static Path reportFile() {
		Path target = Paths.get("target");
		return target.toFile().isDirectory() ? target.resolve("kernel-adversarial-declines.txt")
				: Paths.get("kernel-adversarial-declines.txt");
	}
